with parsed as (select id, service, host, log_ts, level, status_code, payload_json, coalesce(context['trace'], 'none') as trace_or_default, get_json_object(payload_json, '$.duration') as duration_text, array_contains(map_keys(context), 'trace') as has_trace from app_logs) select id, log_ts, level, duration_text, has_trace, lag(status_code) over (partition by level, service order by status_code, id) as prev_status_code, row_number() over (partition by level, service order by status_code, id) as row_seq from parsed where to_date(log_ts) >= '2025-07-01';
